import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.CZo9GF0W.js";const p=JSON.parse('{"title":"Azure Database and Azure SQL","description":"","frontmatter":{},"headers":[],"relativePath":"recipes/azure.md","filePath":"recipes/azure.md","lastUpdated":1789060268000}'),i={name:"recipes/azure.md"};function o(n,e,d,h,l,c){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="azure-database-and-azure-sql" tabindex="-1">Azure Database and Azure SQL <a class="header-anchor" href="#azure-database-and-azure-sql" aria-label="Permalink to &quot;Azure Database and Azure SQL&quot;">​</a></h1><h2 id="azure-database-for-postgresql-flexible-server" tabindex="-1">Azure Database for PostgreSQL (Flexible Server) <a class="header-anchor" href="#azure-database-for-postgresql-flexible-server" aria-label="Permalink to &quot;Azure Database for PostgreSQL (Flexible Server)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Host</td><td><code>orders.postgres.database.azure.com</code></td></tr><tr><td>Port</td><td><code>5432</code></td></tr><tr><td>Database</td><td>your database</td></tr><tr><td>User</td><td><code>analyst</code> — Flexible Server takes the plain user name. The old <code>user@servername</code> form is Single Server, which is retired</td></tr><tr><td>SSL mode</td><td><code>verify-full</code></td></tr><tr><td>CA certificate</td><td>usually unnecessary — Azure&#39;s certificates chain to the DigiCert roots your system already trusts</td></tr></tbody></table><p>Add the connecting address to the server&#39;s firewall rules. Under Remote-SSH that is the remote&#39;s egress address.</p><p>A <strong>private access</strong> (VNet-integrated) server is not reachable from outside the VNet at all: connect from a VM in the VNet over Remote-SSH, or through <a href="./ssh">a bastion</a>.</p><h2 id="azure-database-for-mysql" tabindex="-1">Azure Database for MySQL <a class="header-anchor" href="#azure-database-for-mysql" aria-label="Permalink to &quot;Azure Database for MySQL&quot;">​</a></h2><p>The same, on port 3306, with the MySQL driver. Flexible Server likewise takes the plain user name.</p><h2 id="azure-sql-database-and-managed-instance" tabindex="-1">Azure SQL Database and Managed Instance <a class="header-anchor" href="#azure-sql-database-and-managed-instance" aria-label="Permalink to &quot;Azure SQL Database and Managed Instance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Host</td><td><code>orders.database.windows.net</code></td></tr><tr><td>Port</td><td><code>1433</code></td></tr><tr><td>Database</td><td>the database name — Azure SQL has no cross-database queries, so this one matters</td></tr><tr><td>User</td><td><code>analyst</code></td></tr><tr><td>Encrypt</td><td><strong>on</strong></td></tr><tr><td>Trust server certificate</td><td><strong>off</strong></td></tr></tbody></table><h3 id="the-two-tls-switches" tabindex="-1">The two TLS switches <a class="header-anchor" href="#the-two-tls-switches" aria-label="Permalink to &quot;The two TLS switches&quot;">​</a></h3><p>SQL Server does not have one TLS setting, it has two, and they are frequently set to the wrong pair:</p><ul><li><strong>Encrypt</strong> — whether the connection is encrypted at all.</li><li><strong>Trust server certificate</strong> — whether to skip verifying the certificate.</li></ul><p><code>Encrypt on</code> + <code>Trust off</code> is verified encryption, and is what Azure SQL should always use. <code>Encrypt on</code> + <code>Trust on</code> is encrypted but unauthenticated: it is what a local dev container with a self-signed certificate needs, and it is never what a production server needs. Pitta badges a connection with <code>Trust on</code> as insecure TLS, on purpose.</p><h3 id="entra-id-azure-ad-authentication" tabindex="-1">Entra ID (Azure AD) authentication <a class="header-anchor" href="#entra-id-azure-ad-authentication" aria-label="Permalink to &quot;Entra ID (Azure AD) authentication&quot;">​</a></h3><p>Access tokens expire, so store nothing: use <code>{ &quot;kind&quot;: &quot;prompt&quot; }</code> and paste a fresh one.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">az</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> account</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get-access-token</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --resource</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://database.windows.net/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --query</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> accessToken</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsv</span></span></code></pre></div><h3 id="serverless-tiers-pause" tabindex="-1">Serverless tiers pause <a class="header-anchor" href="#serverless-tiers-pause" aria-label="Permalink to &quot;Serverless tiers pause&quot;">​</a></h3><p>A serverless Azure SQL database that has auto-paused takes 30–60 seconds to resume, and the first connection attempt usually times out before it does. Raise the profile&#39;s connect timeout, or connect twice.</p><h3 id="managed-instance" tabindex="-1">Managed Instance <a class="header-anchor" href="#managed-instance" aria-label="Permalink to &quot;Managed Instance&quot;">​</a></h3><p>Same shape, but the endpoint is private and often on port 3342 for the public endpoint. Connect from inside the VNet, or through <a href="./ssh">a bastion</a>.</p><h2 id="things-that-look-like-bugs" tabindex="-1">Things that look like bugs <a class="header-anchor" href="#things-that-look-like-bugs" aria-label="Permalink to &quot;Things that look like bugs&quot;">​</a></h2><ul><li><strong><code>Cannot open server … requested by the login</code>.</strong> The firewall rule, not the password. Azure returns a login error for a blocked address.</li><li><strong><code>The certificate chain was issued by an authority that is not trusted</code>.</strong> Trust server certificate is off — correct — and something is intercepting TLS, or you are connecting to a local server with a self-signed certificate rather than to Azure.</li><li><strong>Login works in SSMS, fails in Pitta.</strong> SSMS defaults to trusting the server certificate. Pitta does not. That is the difference, and SSMS&#39;s default is the wrong one.</li></ul>',22)])])}const b=t(i,[["render",o]]);export{p as __pageData,b as default};
